/bin/bash -lc "node --input-type=module <<'EOF'
import { chromium } from '@playwright/test'
import { instant } from '@next/playwright'

const browser = await chromium.launch({ headless: true })
const page = await browser.newPage()
try {
  await page.goto('http://localhost:3100/')
  await page.waitForTimeout(1000)
  await instant(page, async () => {
    await page.getByRole('link', { name: 'View Product' }).click()
    await page.waitForURL('**/product', { timeout: 5000 })
    const title = await page.getByRole('heading', { name: 'Premium Widget' }).isVisible()
    const loading = await page.getByText('Loading inventory...').isVisible()
    console.log(JSON.stringify({ title, loading }))
    if ("'!title || !loading) throw new Error('"'Expected title and inventory fallback in instant UI')
  })
  const stock = await page.getByText(/in stock/).isVisible()
  console.log(JSON.stringify({ stock }))
} finally {
  await browser.close()
}
EOF"

/bin/bash -lc "node --input-type=module <<'EOF'
import { chromium, expect } from '@playwright/test'
import { instant } from '@next/playwright'

const browser = await chromium.launch({ headless: true })
const page = await browser.newPage()
try {
  await page.goto('http://localhost:3100/')
  await page.waitForTimeout(500)
  await instant(page, async () => {
    await page.getByRole('link', { name: 'View Product' }).click()
    await page.waitForURL('**/product')
    await expect(page.getByRole('heading', { name: 'Premium Widget' })).toBeVisible()
    await expect(page.getByText('Loading inventory...')).toBeVisible()
  })
  await expect(page.getByText(/\\d+ in stock/)).toBeVisible()
  await expect(page.getByText(/Price: \\"'$'"\\d+\\.\\d{2}/)).toBeVisible()
  await expect(page.getByText('Loading inventory...')).toHaveCount(0)
  console.log('Navigation shell and streamed inventory verified')
} finally {
  await browser.close()
}
EOF"

